[Hookable(false)]
public static UPSVendPriceGroup find(UPSVendPriceGroupId _vendPriceGroupId, boolean _forUpdate = false)
{
    UPSVendPriceGroup vendPriceGroup;

    vendPriceGroup.selectForUpdate(_forUpdate);

    if (_vendPriceGroupId)
    {
        select firstOnly vendPriceGroup
            where vendPriceGroup.VendPriceGroupId == _vendPriceGroupId;
    }

    return vendPriceGroup;
}

static boolean exist(UPSVendPriceGroupId _vendPricegroupId, boolean _silent = true)
{
    if (_vendPricegroupId)
    {
        UPSVendPriceGroup vendPriceGroup;

        select firstonly RecId from vendPriceGroup
            index hint GroupIdx
            where vendPriceGroup.VendPriceGroupId == _vendPricegroupId;

        if (! _silent && ! vendPriceGroup)
        {
            return checkFailed(strFmt("@SYS14690", _vendPricegroupId));
        }
        else
        {
            return vendPriceGroup.RecId != 0;
        }
    }

    return false;
}

public static void vendPriceGroupIdLookup(FormControl _callingControl)
{
    Query                query = new Query();
    QueryBuildDataSource qbds;
    SysTableLookup       sysTableLookup = SysTableLookup::newParameters(tableNum(UPSVendPriceGroup), _callingControl);

    sysTableLookup.addLookupfield(fieldNum(UPSVendPriceGroup, VendPriceGroupId));
    sysTableLookup.addLookupfield(fieldNum(UPSVendPriceGroup, Description));

    qbds = query.addDataSource(tableNum(UPSVendPriceGroup));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
